// ── DB row → Vendor ───────────────────────────────────────────────────────────
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function rowToVendor(row: any): Vendor {
  return {
    id: row.id,
    name: row.name ?? "",
    category: row.category ?? "",
    tier: (row.tier ?? "medium") as VendorTier,
    status: (row.status ?? "active") as VendorStatus,
    riskScore: Number(row.risk_score ?? 50),
    assessmentStatus: (row.assessment_status ?? "not-started") as AssessmentStatus,
    lastAssessment: row.last_assessment ?? "",
    nextAssessment: row.next_assessment ?? "",
    contractExpiry: row.contract_expiry ?? "",
    dataAccess: Array.isArray(row.data_access) ? row.data_access : [],
    certifications: Array.isArray(row.certifications) ? row.certifications : [],
    contacts: Array.isArray(row.contacts) ? row.contacts : [],
    findings: Array.isArray(row.findings) ? (row.findings as VendorFinding[]) : [],
    notes: row.notes ?? "",
    hasBreachHistory: Boolean(row.has_breach_history),
    subprocessors: Boolean(row.subprocessors),
  };
}

