function riskColor(score: number): string {
  if (score <= 25) return "text-green-400";
  if (score <= 50) return "text-yellow-500";
  if (score <= 70) return "text-orange-400";
  return "text-red-400";
}

function riskBarColor(score: number): string {
  if (score <= 25) return "bg-green-500";
  if (score <= 50) return "bg-yellow-500";
  if (score <= 70) return "bg-orange-400";
  return "bg-red-500";
}

function daysUntil(dateStr: string): number {
  return Math.ceil((new Date(dateStr).getTime() - Date.now()) / 86400000);
}

export default function VendorRisk() {
  const { toast } = useToast();
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [filterTier, setFilterTier] = useState<VendorTier | "all">("all");
  const [filterStatus, setFilterStatus] = useState<VendorStatus | "all">("all");
  const [selected, setSelected] = useState<Vendor | null>(null);
  const [assessOpen, setAssessOpen] = useState(false);
  const [assessTarget, setAssessTarget] = useState<Vendor | null>(null);
  const [questAnswers, setQuestAnswers] = useState<Record<string, boolean>>({});
  const [addOpen, setAddOpen] = useState(false);
  const [newVendorName, setNewVendorName] = useState("");
  const [newVendorCat, setNewVendorCat] = useState("Cloud Infrastructure");

  const fetchVendors = async () => {
    setLoading(true);
    setError(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data, error: err } = await (supabase as any)
      .from("vendors")
      .select("*")
      .order("name");
    if (err) {
      setError(err.message);
      toast({ title: "Failed to load vendors", description: err.message, variant: "destructive" });
    } else {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setVendors((data as any[]).map(rowToVendor));
    }
    setLoading(false);
  };

  useEffect(() => { fetchVendors(); }, []);

  const filtered = useMemo(() => vendors.filter(v => {
    const q = search.toLowerCase();
    const matchSearch = !q || v.name.toLowerCase().includes(q) || v.category.toLowerCase().includes(q);
    const matchTier = filterTier === "all" || v.tier === filterTier;
    const matchStatus = filterStatus === "all" || v.status === filterStatus;
    return matchSearch && matchTier && matchStatus;
  }), [vendors, search, filterTier, filterStatus]);

  const stats = useMemo(() => {
    const critical = vendors.filter(v => v.tier === "critical").length;
    const highRisk = vendors.filter(v => v.riskScore > 50).length;
    const overdue = vendors.filter(v => v.assessmentStatus === "overdue").length;
    const openFindings = vendors.reduce((s, v) => s + v.findings.filter(f => f.status === "open").length, 0);
    return { total: vendors.length, critical, highRisk, overdue, openFindings };
  }, [vendors]);

  const allFindings = useMemo(() =>
    vendors.flatMap(v => v.findings.map(f => ({ ...f, vendorName: v.name, vendorId: v.id }))),
    [vendors]);

  const complianceMatrix = useMemo(() =>
    vendors.filter(v => v.tier === "critical" || v.tier === "high").map(v => ({
      id: v.id, name: v.name.slice(0, 20),
      certs: FRAMEWORKS.map(fw => ({
        fw, status: v.certifications.includes(fw) ? "certified" : v.tier === "critical" && !v.certifications.includes(fw) ? "missing" : "unknown",
      })),
    })),
    [vendors]);

  const startAssessment = (v: Vendor) => {
    setAssessTarget(v);
    const initial: Record<string, boolean> = {};
    QUESTIONNAIRE.forEach(q => { initial[q.field] = false; });
    setQuestAnswers(initial);
    setAssessOpen(true);
  };

  const submitAssessment = async () => {
    if (!assessTarget) return;
    const score = Math.min(100, QUESTIONNAIRE.reduce((s, q) => s + (questAnswers[q.field] ? q.yesScore : q.noScore), 0));
    const today = new Date().toISOString().slice(0, 10);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error: err } = await (supabase as any)
      .from("vendors")
      .update({ risk_score: score, assessment_status: "completed", last_assessment: today })
      .eq("id", assessTarget.id);
    if (err) {
      toast({ title: "Assessment save failed", description: err.message, variant: "destructive" });
    } else {
      await fetchVendors();
      if (selected?.id === assessTarget.id) {
        setSelected(prev => prev ? { ...prev, riskScore: score, assessmentStatus: "completed", lastAssessment: today } : prev);
      }
      toast({ title: "Assessment submitted", description: `${assessTarget.name} — Risk score: ${score}` });
    }
    setAssessOpen(false);
    setAssessTarget(null);
  };

  const addVendor = async () => {
    if (!newVendorName.trim()) { toast({ title: "Name required", variant: "destructive" }); return; }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error: err } = await (supabase as any)
      .from("vendors")
      .insert([{
        name: newVendorName, category: newVendorCat, tier: "medium", status: "active",
        risk_score: 50, assessment_status: "not-started",
        data_access: [], certifications: [], contacts: [], findings: [],
        notes: "", has_breach_history: false, subprocessors: false,
      }])
      .select();
    if (err) {
      toast({ title: "Add vendor failed", description: err.message, variant: "destructive" });
    } else {
      await fetchVendors();
      setAddOpen(false);
      setNewVendorName("");
      toast({ title: "Vendor added", description: newVendorName });
    }
  };

  const exportReport = () => {
    const data = JSON.stringify({ generated: new Date().toISOString(), vendors: filtered }, null, 2);
    const blob = new Blob([data], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a"); a.href = url; a.download = "vendor-risk-report.json"; a.click();
    toast({ title: "Report exported" });
  };

  const VendorRow = ({ v }: { v: Vendor }) => (
    <div className="flex flex-wrap items-center gap-2 px-4 py-3 border-b border-border/40 hover:bg-muted/30 cursor-pointer transition-colors" onClick={() => setSelected(v)}>
      <div className="flex-1 min-w-[160px]">
        <div className="font-medium text-sm truncate">{v.name}</div>
        <div className="text-xs text-muted-foreground">{v.category}</div>
      </div>
      <div className="w-24"><Badge variant="outline" className={`text-xs ${TIER_COLORS[v.tier]}`}>{v.tier}</Badge></div>
      <div className="w-28"><Badge variant="outline" className={`text-xs ${STATUS_COLORS[v.status]}`}>{v.status}</Badge></div>
      <div className="w-32 hidden md:flex items-center gap-2">
        <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
          <div className={`h-full rounded-full ${riskBarColor(v.riskScore)}`} style={{ width: `${v.riskScore}%` }} />
        </div>
        <span className={`text-xs font-mono w-6 ${riskColor(v.riskScore)}`}>{v.riskScore}</span>
      </div>
      <div className="w-28 hidden lg:block"><Badge variant="outline" className={`text-xs ${ASSESSMENT_COLORS[v.assessmentStatus]}`}>{v.assessmentStatus}</Badge></div>
      <div className="w-20 hidden xl:block text-xs text-muted-foreground">{v.lastAssessment || "Never"}</div>
      <div className="w-16 hidden xl:block text-xs text-center">
        {v.findings.filter(f => f.status === "open").length > 0
          ? <span className="text-red-400 font-bold">{v.findings.filter(f => f.status === "open").length}</span>
          : <span className="text-green-400">0</span>}
      </div>
      <ChevronRight className="w-4 h-4 text-muted-foreground" />
    </div>
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 gap-3 text-muted-foreground">
        <Loader2 className="w-5 h-5 animate-spin" />
        <span className="text-sm">Loading vendors…</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-3">
        <AlertTriangle className="w-8 h-8 text-destructive" />
        <p className="text-sm font-medium text-destructive">Failed to load vendors</p>
        <p className="text-xs text-muted-foreground">{error}</p>
        <Button variant="outline" size="sm" onClick={fetchVendors}><RefreshCw className="w-3.5 h-3.5 mr-1" /> Retry</Button>
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 max-w-screen-2xl mx-auto space-y-5">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-bold flex items-center gap-2">
            <Building2 className="w-5 h-5 text-primary" /> Vendor Risk Management
          </h1>
          <p className="text-xs text-muted-foreground mt-0.5">Third-party risk assessments, compliance tracking, and security posture for all vendors</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" size="sm" onClick={exportReport}><Download className="w-3.5 h-3.5 mr-1" /> Export</Button>
          <Button variant="outline" size="sm" onClick={async () => { await fetchVendors(); toast({ title: "Refreshed" }); }}><RefreshCw className="w-3.5 h-3.5 mr-1" /> Refresh</Button>
          <Button size="sm" onClick={() => setAddOpen(true)}><Plus className="w-3.5 h-3.5 mr-1" /> Add Vendor</Button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
        {[
          { label: "Total Vendors", value: stats.total, color: "text-primary" },
          { label: "Critical Tier", value: stats.critical, color: "text-red-400" },
          { label: "High Risk (>50)", value: stats.highRisk, color: "text-orange-400" },
          { label: "Overdue Assessments", value: stats.overdue, color: "text-red-400" },
          { label: "Open Findings", value: stats.openFindings, color: "text-yellow-500" },
        ].map(s => (
          <Card key={s.label} className="border-border/60 bg-card/60">
            <CardContent className="px-4 py-3 text-center">
              <div className={`text-2xl font-bold tabular-nums ${s.color}`}>{s.value}</div>
              <div className="text-xs text-muted-foreground mt-0.5">{s.label}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-2">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-2.5 top-2 w-3.5 h-3.5 text-muted-foreground" />
          <Input placeholder="Search vendors…" className="pl-8 h-8 text-sm" value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <select value={filterTier} onChange={e => setFilterTier(e.target.value as VendorTier | "all")} className="h-8 rounded-md border border-border bg-background px-2 text-sm focus:outline-none">
          <option value="all">All Tiers</option>
          {(["critical", "high", "medium", "low"] as VendorTier[]).map(t => <option key={t} value={t}>{t}</option>)}
        </select>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value as VendorStatus | "all")} className="h-8 rounded-md border border-border bg-background px-2 text-sm focus:outline-none">
          <option value="all">All Statuses</option>
          {(["active", "under-review", "suspended", "offboarded"] as VendorStatus[]).map(s => <option key={s} value={s}>{s}</option>)}
        </select>
      </div>

      <Tabs defaultValue="vendors">
        <TabsList className="h-8">
          <TabsTrigger value="vendors" className="text-xs">Vendors ({filtered.length})</TabsTrigger>
          <TabsTrigger value="findings" className="text-xs">Findings ({allFindings.filter(f => f.status === "open").length})</TabsTrigger>
          <TabsTrigger value="compliance" className="text-xs">Compliance Matrix</TabsTrigger>
          <TabsTrigger value="reports" className="text-xs">Reports</TabsTrigger>
        </TabsList>

        {/* ── Vendors Tab ── */}
        <TabsContent value="vendors" className="mt-3">
          <div className="rounded-md border border-border/60 overflow-hidden">
            <div className="flex flex-wrap items-center gap-2 px-4 py-2 border-b border-border/60 text-xs text-muted-foreground font-medium bg-muted/20">
              <div className="flex-1 min-w-[160px]">Vendor</div>
              <div className="w-24">Tier</div>
              <div className="w-28">Status</div>
              <div className="w-32 hidden md:block">Risk Score</div>
              <div className="w-28 hidden lg:block">Assessment</div>
              <div className="w-20 hidden xl:block">Last Assessed</div>
              <div className="w-16 text-center hidden xl:block">Findings</div>
              <div className="w-4" />
            </div>
            {filtered.length === 0
              ? <div className="text-center py-12 text-muted-foreground text-sm"><Building2 className="w-8 h-8 mx-auto mb-2 opacity-20" />No vendors match filters.</div>
              : filtered.map(v => <VendorRow key={v.id} v={v} />)}
          </div>
        </TabsContent>

        {/* ── Findings Tab ── */}
        <TabsContent value="findings" className="mt-3 space-y-2">
          {allFindings.filter(f => f.status === "open").length === 0
            ? <div className="text-center py-12 text-muted-foreground text-sm"><CheckCircle2 className="w-8 h-8 mx-auto mb-2 text-green-400 opacity-60" />No open findings.</div>
            : allFindings.filter(f => f.status === "open").sort((a, b) => {
              const order = { critical: 0, high: 1, medium: 2, low: 3 };
              return order[a.severity] - order[b.severity];
            }).map(f => (
              <div key={f.id} className="flex items-start gap-3 p-3 rounded-lg border border-border/60 bg-card/60">
                <Badge variant="outline" className={`text-xs shrink-0 mt-0.5 ${FINDING_COLORS[f.severity]}`}>{f.severity.toUpperCase()}</Badge>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="font-medium text-sm">{f.title}</span>
                    <span className="text-xs text-muted-foreground">— {f.vendorName}</span>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">{f.description}</p>
                  <div className="flex items-center gap-2 mt-1.5">
                    <span className="text-xs text-muted-foreground flex items-center gap-1">
                      <Clock className="w-3 h-3" /> Due: {f.dueDate}
                      {daysUntil(f.dueDate) < 0 && <span className="text-red-400 font-medium">(overdue)</span>}
                      {daysUntil(f.dueDate) >= 0 && daysUntil(f.dueDate) <= 7 && <span className="text-orange-400 font-medium">({daysUntil(f.dueDate)}d left)</span>}
                    </span>
                  </div>
                </div>
                <Button variant="outline" size="sm" className="h-7 text-xs shrink-0" onClick={() => { const v = vendors.find(v => v.id === f.vendorId); if (v) setSelected(v); }}>
                  View Vendor
                </Button>
              </div>
            ))}
        </TabsContent>

        {/* ── Compliance Matrix Tab ── */}
        <TabsContent value="compliance" className="mt-3">
          <div className="overflow-x-auto rounded-lg border border-border/60">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-border/60 bg-muted/30">
                  <th className="text-left px-3 py-2 font-medium text-muted-foreground">Vendor</th>
                  {FRAMEWORKS.map(fw => <th key={fw} className="text-center px-3 py-2 font-medium text-muted-foreground">{fw}</th>)}
                </tr>
              </thead>
              <tbody className="divide-y divide-border/30">
                {complianceMatrix.map(row => (
                  <tr key={row.id} className="hover:bg-muted/20">
                    <td className="px-3 py-2 font-medium">{row.name}</td>
                    {row.certs.map(c => (
                      <td key={c.fw} className="px-3 py-2 text-center">
                        {c.status === "certified"
                          ? <CheckCircle2 className="w-4 h-4 text-green-400 mx-auto" />
                          : c.status === "missing"
                          ? <X className="w-4 h-4 text-red-400 mx-auto" />
                          : <span className="text-muted-foreground/40">—</span>}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex gap-4 mt-3 text-xs text-muted-foreground">
            <div className="flex items-center gap-1.5"><CheckCircle2 className="w-3.5 h-3.5 text-green-400" /> Certified</div>
            <div className="flex items-center gap-1.5"><X className="w-3.5 h-3.5 text-red-400" /> Missing (critical/high tier)</div>
            <div className="flex items-center gap-1.5"><span className="text-muted-foreground/40 font-bold">—</span> Unknown / N/A</div>
          </div>
        </TabsContent>

        {/* ── Reports Tab ── */}
        <TabsContent value="reports" className="mt-3 space-y-4">
          {/* Risk distribution */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><BarChart3 className="w-4 h-4 text-primary" />Risk Score Distribution</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              {[
                { label: "Low (0-25)", count: vendors.filter(v => v.riskScore <= 25).length, color: "bg-green-500/60" },
                { label: "Medium (26-50)", count: vendors.filter(v => v.riskScore > 25 && v.riskScore <= 50).length, color: "bg-yellow-500/60" },
                { label: "High (51-70)", count: vendors.filter(v => v.riskScore > 50 && v.riskScore <= 70).length, color: "bg-orange-500/60" },
                { label: "Critical (71-100)", count: vendors.filter(v => v.riskScore > 70).length, color: "bg-red-500/60" },
              ].map(d => (
                <div key={d.label} className="flex items-center gap-3">
                  <span className="text-xs text-muted-foreground w-32">{d.label}</span>
                  <div className="flex-1 h-5 bg-muted/30 rounded overflow-hidden">
                    <div className={`h-full rounded ${d.color}`} style={{ width: `${vendors.length > 0 ? (d.count / vendors.length) * 100 : 0}%` }} />
                  </div>
                  <span className="text-xs font-medium w-6 text-right">{d.count}</span>
                </div>
              ))}
            </CardContent>
          </Card>

          {/* Top risky vendors */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><AlertTriangle className="w-4 h-4 text-red-400" />Top 5 Highest Risk Vendors</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              {[...vendors].sort((a, b) => b.riskScore - a.riskScore).slice(0, 5).map((v, i) => (
                <div key={v.id} className="flex items-center gap-3 cursor-pointer hover:bg-muted/20 p-1 rounded" onClick={() => setSelected(v)}>
                  <span className="text-xs text-muted-foreground w-4">{i + 1}.</span>
                  <span className="text-sm flex-1 font-medium">{v.name}</span>
                  <Badge variant="outline" className={`text-xs ${TIER_COLORS[v.tier]}`}>{v.tier}</Badge>
                  <span className={`text-sm font-bold w-8 text-right font-mono ${riskColor(v.riskScore)}`}>{v.riskScore}</span>
                </div>
              ))}
            </CardContent>
          </Card>

          {/* Contract expiry (next 90 days) */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Clock className="w-4 h-4 text-orange-400" />Contracts Expiring in 90 Days</CardTitle></CardHeader>
            <CardContent>
              {vendors.filter(v => v.contractExpiry && daysUntil(v.contractExpiry) <= 90 && daysUntil(v.contractExpiry) >= 0).length === 0
                ? <p className="text-sm text-muted-foreground">No contracts expiring in the next 90 days.</p>
                : vendors.filter(v => v.contractExpiry && daysUntil(v.contractExpiry) <= 90 && daysUntil(v.contractExpiry) >= 0)
                  .sort((a, b) => daysUntil(a.contractExpiry) - daysUntil(b.contractExpiry))
                  .map(v => (
                    <div key={v.id} className="flex items-center justify-between py-2 border-b border-border/30 last:border-0">
                      <span className="text-sm font-medium">{v.name}</span>
                      <div className="flex items-center gap-3">
                        <span className="text-xs text-muted-foreground">{v.contractExpiry}</span>
                        <span className={`text-xs font-bold ${daysUntil(v.contractExpiry) <= 30 ? "text-red-400" : "text-orange-400"}`}>{daysUntil(v.contractExpiry)}d left</span>
                      </div>
                    </div>
                  ))}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Vendor Detail Dialog */}
      <Dialog open={!!selected} onOpenChange={v => { if (!v) setSelected(null); }}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          {selected && (
            <>
              <DialogHeader>
                <DialogTitle className="flex items-center gap-2 flex-wrap">
                  <Building2 className="w-4 h-4 text-primary" />
                  {selected.name}
                  <Badge variant="outline" className={`text-xs ${TIER_COLORS[selected.tier]}`}>{selected.tier}</Badge>
                  <Badge variant="outline" className={`text-xs ${STATUS_COLORS[selected.status]}`}>{selected.status}</Badge>
                </DialogTitle>
              </DialogHeader>
              <div className="space-y-4 pt-1">
                {/* Risk score */}
                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span className="text-muted-foreground">Risk Score</span>
                    <span className={`font-bold ${riskColor(selected.riskScore)}`}>{selected.riskScore}/100</span>
                  </div>
                  <Progress value={selected.riskScore} className="h-2" />
                </div>
                {/* Details grid */}
                <div className="grid grid-cols-2 gap-x-6 gap-y-1.5 text-xs">
                  <div><span className="text-muted-foreground">Category:</span> <span>{selected.category}</span></div>
                  <div><span className="text-muted-foreground">Assessment:</span> <Badge variant="outline" className={`text-xs ml-1 ${ASSESSMENT_COLORS[selected.assessmentStatus]}`}>{selected.assessmentStatus}</Badge></div>
                  <div><span className="text-muted-foreground">Last Assessed:</span> <span>{selected.lastAssessment || "Never"}</span></div>
                  <div><span className="text-muted-foreground">Next Assessment:</span> <span className={selected.nextAssessment && daysUntil(selected.nextAssessment) < 0 ? "text-red-400" : ""}>{selected.nextAssessment || "TBD"}</span></div>
                  <div><span className="text-muted-foreground">Contract Expiry:</span> <span>{selected.contractExpiry || "Unknown"}</span></div>
                  <div><span className="text-muted-foreground">Breach History:</span> <span className={selected.hasBreachHistory ? "text-red-400 font-medium" : "text-green-400"}>{selected.hasBreachHistory ? "Yes" : "No"}</span></div>
                  <div><span className="text-muted-foreground">Sub-processors:</span> <span>{selected.subprocessors ? "Yes" : "No"}</span></div>
                </div>
                {/* Data access */}
                {selected.dataAccess.length > 0 && (
                  <div>
                    <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">Data Access</p>
                    <div className="flex flex-wrap gap-1">
                      {selected.dataAccess.map(d => <Badge key={d} variant="outline" className="text-xs text-orange-400 border-orange-500/40">{d}</Badge>)}
                    </div>
                  </div>
                )}
                {/* Certifications */}
                <div>
                  <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">Certifications</p>
                  {selected.certifications.length === 0
                    ? <span className="text-xs text-red-400">No certifications on file</span>
                    : <div className="flex flex-wrap gap-1">{selected.certifications.map(c => <Badge key={c} variant="outline" className="text-xs text-green-400 border-green-500/40">{c}</Badge>)}</div>}
                </div>
                {/* Open findings */}
                {selected.findings.filter(f => f.status === "open").length > 0 && (
                  <div>
                    <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">Open Findings ({selected.findings.filter(f => f.status === "open").length})</p>
                    <div className="space-y-2">
                      {selected.findings.filter(f => f.status === "open").map(f => (
                        <div key={f.id} className="p-2 rounded-md border border-border/60 bg-muted/20">
                          <div className="flex items-center gap-2 mb-1">
                            <Badge variant="outline" className={`text-xs ${FINDING_COLORS[f.severity]}`}>{f.severity}</Badge>
                            <span className="text-xs font-medium">{f.title}</span>
                          </div>
                          <p className="text-xs text-muted-foreground">{f.description}</p>
                          <p className="text-xs text-muted-foreground mt-1">Due: {f.dueDate}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {/* Notes */}
                {selected.notes && (
                  <div>
                    <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">Notes</p>
                    <p className="text-xs text-muted-foreground bg-muted/20 rounded p-2">{selected.notes}</p>
                  </div>
                )}
              </div>
              <DialogFooter className="flex gap-2 flex-wrap">
                <Button variant="outline" size="sm" onClick={() => startAssessment(selected)}>
                  <Shield className="w-3.5 h-3.5 mr-1" /> Run Assessment
                </Button>
                <Button variant="ghost" size="sm" onClick={() => setSelected(null)}>Close</Button>
              </DialogFooter>
            </>
          )}
        </DialogContent>
      </Dialog>

      {/* Assessment Questionnaire Dialog */}
      <Dialog open={assessOpen} onOpenChange={v => { if (!v) setAssessOpen(false); }}>
        <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Security Assessment — {assessTarget?.name}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <p className="text-xs text-muted-foreground">Answer the questions below to calculate the vendor risk score. Risk score = sum of penalty points for negative answers.</p>
            {QUESTIONNAIRE.map(q => (
              <div key={q.id} className="flex items-start gap-3 p-3 rounded-lg border border-border/50 bg-muted/20">
                <div className="flex-1 text-sm">{q.question}</div>
                <div className="flex gap-2 shrink-0">
                  <button onClick={() => setQuestAnswers(a => ({ ...a, [q.field]: true }))} className={`px-3 py-1 rounded text-xs border transition-colors ${questAnswers[q.field] === true ? "bg-green-500/20 border-green-400 text-green-300" : "border-border text-muted-foreground hover:border-green-400"}`}>Yes</button>
                  <button onClick={() => setQuestAnswers(a => ({ ...a, [q.field]: false }))} className={`px-3 py-1 rounded text-xs border transition-colors ${questAnswers[q.field] === false ? "bg-red-500/20 border-red-400 text-red-300" : "border-border text-muted-foreground hover:border-red-400"}`}>No</button>
                </div>
              </div>
            ))}
            <div className="p-3 rounded-lg bg-muted/30 border border-border/60">
              <div className="flex justify-between text-sm">
                <span className="font-medium">Calculated Risk Score</span>
                <span className={`font-bold ${riskColor(Math.min(100, QUESTIONNAIRE.reduce((s, q) => s + (questAnswers[q.field] ? q.yesScore : q.noScore), 0)))}`}>
                  {Math.min(100, QUESTIONNAIRE.reduce((s, q) => s + (questAnswers[q.field] ? q.yesScore : q.noScore), 0))}/100
                </span>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" size="sm" onClick={() => setAssessOpen(false)}>Cancel</Button>
            <Button size="sm" onClick={submitAssessment}>Submit Assessment</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Add Vendor Dialog */}
      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle>Add Vendor</DialogTitle></DialogHeader>
          <div className="space-y-3 py-2">
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Vendor Name *</label>
              <Input value={newVendorName} onChange={e => setNewVendorName(e.target.value)} placeholder="Company name" className="h-8 text-sm" />
            </div>
            <div>
              <label className="text-xs text-muted-foreground mb-1 block">Category</label>
              <Input value={newVendorCat} onChange={e => setNewVendorCat(e.target.value)} placeholder="e.g. Cloud Infrastructure" className="h-8 text-sm" />
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" size="sm" onClick={() => setAddOpen(false)}>Cancel</Button>
            <Button size="sm" onClick={addVendor}>Add Vendor</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
